from typing import List, Sequence

from rosterkit.models import Student


def seating_rows(
    students: Sequence[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, students sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(
        students, key=_sort_key
    )
    names = [s.display_name for s in ordered]
    rows = []
    for start in range(0, len(names), seats_per_row):
        chunk = names[start:start + seats_per_row]
        rows.append(
            f"Row {len(rows) + 1}: " + " | ".join(chunk)
        )
    return rows


def _sort_key(student: Student):
    return (student.last_name.lower(), student.first_name.lower())
