cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student("1", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_rows_sorted_and_split(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abel", "Zed"),
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Abel, Zed | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count(self):
        people = [make("Abel", "Zed")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
EOF
